/* VCD dumping functions */
MOD_mkTbNocNetworkPerf & mkTbNocNetworkPerf_backing(tSimStateHdl simHdl)
{
  static MOD_mkTbNocNetworkPerf *instance = NULL;
  if (instance == NULL)
  {
    vcd_set_backing_instance(simHdl, true);
    instance = new MOD_mkTbNocNetworkPerf(simHdl, "top", NULL);
    vcd_set_backing_instance(simHdl, false);
  }
  return *instance;
}
void MODEL_mkTbNocNetworkPerf::dump_VCD_defs()
{
  (mkTbNocNetworkPerf_instance->dump_VCD_defs)(vcd_depth(sim_hdl));
}
void MODEL_mkTbNocNetworkPerf::dump_VCD(tVCDDumpType dt)
{
  (mkTbNocNetworkPerf_instance->dump_VCD)(dt,
					  vcd_depth(sim_hdl),
					  mkTbNocNetworkPerf_backing(sim_hdl));
}
